<template>
  <view class="detail-page">
    <view class="status-hero" :class="statusTone"><view class="status-icon"><image :src="statusIcon" /></view><view><view class="status-title">{{ statusText }}</view><text>{{ statusDescription }}</text></view></view>

    <view class="section"><view class="section-title">服务信息</view><view class="service-row"><view class="game-icon"><image src="/static/icons/gamepad.png"/></view><view><view>{{ game.gameName || detail.productName || '陪玩服务' }}</view><text>{{ firstItem.skuName || firstItem.productName || '默认服务规格' }}</text></view></view><view class="field"><text>区服 / 段位</text><label>{{ [game.serverName,game.rankName].filter(Boolean).join(' · ') || '未填写' }}</label></view><view class="field"><text>游戏昵称</text><label>{{ game.gameNickname || '未填写' }}</label></view><view class="field"><text>服务要求</text><label class="wrap">{{ game.extraRequirement || detail.customerRemark || '无额外要求' }}</label></view></view>

    <view v-if="(detail.commitments as RecordData[] || []).length" class="section commitment-section"><view class="section-title">本单承诺</view><view v-for="rule in (detail.commitments as RecordData[] || [])" :key="String(rule.id)" class="commitment-row"><view><strong>{{ rule.title }}</strong><text v-if="rule.description">{{ rule.description }}</text><text v-if="rule.failureAction">未达标处理：{{ rule.failureAction }}</text></view><label v-if="targetText(rule)">{{ targetText(rule) }}</label></view></view>

    <view class="section"><view class="section-title">联系与时间</view><view class="field"><text>联系人</text><label>{{ detail.contactName || '未填写' }}</label></view><view class="field"><text>联系电话</text><label>{{ detail.contactPhone || '未填写' }}</label></view><view class="field"><text>接单时间</text><label>{{ formatTime(detail.assignedAt) }}</label></view><view class="field"><text>开始时间</text><label>{{ formatTime(detail.serviceStartedAt) }}</label></view></view>

    <view class="section"><view class="section-title">服务成员（{{ detail.memberCount || 0 }}/{{ detail.requiredPlayerCount || 1 }}）</view><view v-for="member in (detail.members as RecordData[] || [])" :key="String(member.id)" class="field"><text>{{ member.playerName }}</text><label>{{ memberStatusText(member.memberStatus) }}</label></view></view>

    <view class="section amount-section"><view class="field"><text>商品金额</text><label>¥{{ money(detail.totalAmount) }}</label></view><view class="field total"><text>订单实付</text><label>¥{{ money(detail.payableAmount) }}</label></view></view>

    <view v-if="showProgress" class="section"><view class="section-title">完成确认进度</view><view class="progress"><view class="step done"><view>✓</view><text>陪玩提交</text></view><view class="line" :class="{ done: isReviewed }"/><view class="step" :class="{ done: isReviewed }"><view>{{ isReviewed?'✓':'2' }}</view><text>平台审核</text></view><view class="line" :class="{ done: detail.orderStatus==='COMPLETED' }"/><view class="step" :class="{ done: detail.orderStatus==='COMPLETED' }"><view>{{ detail.orderStatus==='COMPLETED'?'✓':'3' }}</view><text>顾客确认</text></view></view><view class="progress-tip">{{ statusDescription }}</view></view>

    <view class="section"><view class="section-title">订单信息</view><view class="field"><text>订单编号</text><label selectable>{{ detail.orderNo }}</label></view><view class="field"><text>创建时间</text><label>{{ formatTime(detail.createTime) }}</label></view></view>

    <view class="bottom-actions"><button v-if="canStart" class="primary" @click="start">开始服务</button><template v-else-if="canSubmit"><button class="outline" @click="serviceException">转单/炸单</button><button class="primary" @click="submit">提交完成</button></template><button v-else-if="isAbnormal" class="danger" @click="contact">联系客服处理</button><button v-else class="outline" @click="contact">联系平台客服</button></view>
  </view>
</template>

<script setup lang="ts">
import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{getPlayerOrder,startOrder}from'@/api/player';import type{RecordData}from'@/types/api';const id=ref(0),detail=ref<RecordData>({});const game=computed(()=>(detail.value.gameProfile||{})as RecordData);const firstItem=computed(()=>((detail.value.items as RecordData[]||[])[0]||{}));const statuses:Record<string,{text:string;desc:string;tone:string;icon:string}>={ASSIGNED:{text:'待开始服务',desc:'请核对服务信息，确认后开始服务',tone:'waiting',icon:'/static/icons/hourglass.png'},IN_SERVICE:{text:'服务进行中',desc:'服务完成后请及时上传履约凭证',tone:'working',icon:'/static/icons/gamepad.png'},PAUSED:{text:'订单已暂停',desc:'老板申请的暂停已通过，请等待恢复服务',tone:'review',icon:'/static/icons/hourglass.png'},PENDING_CONFIRM:{text:'平台审核中',desc:'完成凭证已提交，正在等待平台审核',tone:'review',icon:'/static/icons/hourglass.png'},WAIT_CUSTOMER_CONFIRM:{text:'等待顾客确认',desc:'平台已审核通过，等待顾客确认服务完成',tone:'review',icon:'/static/icons/hourglass.png'},COMPLETED:{text:'服务已完成',desc:'本次陪玩服务已经完成',tone:'done',icon:'/static/icons/check.png'},CANCELLED:{text:'订单已取消',desc:'订单存在异常或已被取消',tone:'abnormal',icon:'/static/icons/alert.png'},AFTER_SALE:{text:'售后处理中',desc:'平台正在处理本订单的售后问题',tone:'abnormal',icon:'/static/icons/after-sale.png'}};const canStart=computed(()=>['ASSIGNED','IN_SERVICE'].includes(String(detail.value.orderStatus))&&detail.value.memberStatus==='ACCEPTED'),canSubmit=computed(()=>detail.value.orderStatus==='IN_SERVICE'&&detail.value.memberStatus==='IN_SERVICE');const pendingControl=computed(()=>((detail.value.serviceExceptions as RecordData[]||[]).find(x=>['PAUSE','RESUME'].includes(String(x.request_type))&&x.request_status==='PENDING')));const meta=computed(()=>pendingControl.value?{text:pendingControl.value.request_type==='PAUSE'?'暂停审核中':'继续审核中',desc:'平台正在审核老板提交的服务变更申请',tone:'review',icon:'/static/icons/hourglass.png'}:canStart.value&&detail.value.orderStatus==='IN_SERVICE'?{text:'待本人开始服务',desc:'已有队友开始服务，请核对信息后确认本人开始',tone:'waiting',icon:'/static/icons/hourglass.png'}:statuses[String(detail.value.orderStatus)]||{text:String(detail.value.orderStatus||'订单详情'),desc:'查看订单服务信息',tone:'waiting',icon:'/static/icons/orders-active.png'});const statusText=computed(()=>meta.value.text),statusDescription=computed(()=>meta.value.desc),statusTone=computed(()=>meta.value.tone),statusIcon=computed(()=>meta.value.icon),showProgress=computed(()=>['PENDING_CONFIRM','WAIT_CUSTOMER_CONFIRM','COMPLETED'].includes(String(detail.value.orderStatus))),isReviewed=computed(()=>['WAIT_CUSTOMER_CONFIRM','COMPLETED'].includes(String(detail.value.orderStatus))),isAbnormal=computed(()=>['CANCELLED','AFTER_SALE'].includes(String(detail.value.orderStatus)));onLoad(async q=>{id.value=Number(q?.id);await load()});async function load(){detail.value=await getPlayerOrder(id.value)}function formatTime(value:unknown){return value?String(value).replace('T',' ').slice(0,16):'--'}function money(value:unknown){return Number(value||0).toFixed(2)}function memberStatusText(value:unknown){return({ACCEPTED:'待开始',IN_SERVICE:'服务中',COMPLETED:'已完成',TRANSFERRED:'已转出',CANCELLED:'已取消'}as Record<string,string>)[String(value)]||String(value||'未知')}function submit(){uni.navigateTo({url:`/subpackages/player/submit?id=${id.value}`})}function start(){uni.showModal({title:'开始服务',content:'确认已核对游戏资料与服务要求？',confirmText:'确认开始',success:async result=>{if(result.confirm){await startOrder(id.value);uni.showToast({title:'服务已开始'});await load()}}})}function contact(){uni.navigateTo({url:`/subpackages/customer/service-tickets?orderId=${id.value}`})}
function serviceException(){uni.navigateTo({url:`/subpackages/player/service-exception?id=${id.value}`})}
function targetText(rule:RecordData){return rule.targetValue===null||rule.targetValue===undefined||rule.targetValue===''?'':`${rule.targetValue}${rule.targetUnit||''}`}
</script>

<style scoped lang="scss">
.detail-page{min-height:100vh;padding:24rpx 24rpx 180rpx;box-sizing:border-box;background:#eee9da}.status-hero{padding:29rpx;border-radius:24rpx;display:flex;align-items:center;gap:20rpx;color:#fffaf0}.status-hero.waiting{background:linear-gradient(110deg,#725c3d,#997a4d)}.status-hero.working{background:linear-gradient(110deg,#23483c,#3f6d5c)}.status-hero.review{background:linear-gradient(110deg,#8a6337,#b4874f)}.status-hero.done{background:linear-gradient(110deg,#5c6962,#7d8a83)}.status-hero.abnormal{background:linear-gradient(110deg,#7d342c,#a44d40)}.status-icon{width:70rpx;height:70rpx;border-radius:20rpx;display:flex;align-items:center;justify-content:center;background:rgba(255,250,240,.92)}.status-icon image{width:43rpx;height:43rpx}.status-title{font-size:31rpx;font-weight:800}.status-hero text{display:block;margin-top:7rpx;color:rgba(255,250,240,.72);font-size:19rpx}.section{margin-top:18rpx;padding:25rpx;border:1rpx solid rgba(49,92,80,.14);border-radius:23rpx;background:#fffaf0}.section-title{margin-bottom:18rpx;color:#263a31;font-family:STKaiti,KaiTi,serif;font-size:28rpx;font-weight:800}.service-row{display:flex;align-items:center;gap:16rpx;margin-bottom:12rpx;padding-bottom:19rpx;border-bottom:1rpx solid rgba(49,92,80,.1)}.game-icon{width:66rpx;height:66rpx;border-radius:18rpx;display:flex;align-items:center;justify-content:center;background:#e1e8dd}.game-icon image{width:41rpx;height:41rpx}.service-row>view:last-child view{font-weight:700}.service-row text{display:block;margin-top:6rpx;color:#89928c;font-size:20rpx}.field{min-height:70rpx;display:flex;align-items:center;justify-content:space-between;gap:28rpx;border-bottom:1rpx solid rgba(49,92,80,.09)}.field:last-child{border:0}.field text{flex:none;color:#879189;font-size:21rpx}.field label{color:#405148;font-size:21rpx;text-align:right}.field label.wrap{padding:13rpx 0;line-height:1.5}.amount-section .field label{font-weight:700}.amount-section .total label{color:#963d31;font-size:28rpx}.progress{padding:18rpx 4rpx;display:flex;align-items:flex-start}.step{width:105rpx;text-align:center;color:#a8ada8}.step view{width:43rpx;height:43rpx;margin:auto;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff;background:#c4c7c1;font-size:19rpx}.step text{display:block;margin-top:9rpx;font-size:18rpx}.step.done{color:#315c50}.step.done view{background:#315c50}.line{flex:1;height:4rpx;margin-top:20rpx;background:#dedfd8}.line.done{background:#315c50}.progress-tip{padding:14rpx;border-radius:14rpx;color:#7e633d;background:#eee5d3;font-size:19rpx;text-align:center}.bottom-actions{position:fixed;z-index:20;left:0;right:0;bottom:0;padding:16rpx 24rpx calc(16rpx + env(safe-area-inset-bottom));display:flex;gap:14rpx;background:rgba(255,250,240,.97);box-shadow:0 -8rpx 28rpx rgba(38,53,45,.1)}.bottom-actions button{height:82rpx;flex:1;margin:0;border-radius:41rpx;line-height:82rpx;font-size:24rpx}.bottom-actions .primary{color:#fffaf0;background:#315c50}.outline{border:1rpx solid #91a398;color:#315c50;background:#fffaf0}.danger{color:#fffaf0;background:#963d31}
.commitment-section{border-color:rgba(150,61,49,.2);background:linear-gradient(135deg,#fffaf0,#f5e8dc)}.commitment-row{display:flex;align-items:flex-start;justify-content:space-between;gap:18rpx;padding:15rpx 0;border-bottom:1rpx solid rgba(150,61,49,.1)}.commitment-row:last-child{border-bottom:0}.commitment-row>view{min-width:0;flex:1}.commitment-row strong,.commitment-row text{display:block}.commitment-row strong{color:#3d2c25;font-size:23rpx}.commitment-row text{margin-top:6rpx;color:#786c64;font-size:19rpx;line-height:1.5}.commitment-row label{flex:none;color:#963d31;font-size:26rpx;font-weight:800}
</style>
